head.b:skin:
/* ============ WILDLIFE UNIVERSE - Blogger theme (clone of wildlifeuniverse.org) ============ */
*{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;}
img{max-width:100%;display:block;}
a{text-decoration:none;color:inherit;}
:root{
  --c-primary:#008000;--c-primary-deep:#003d00;--c-primary-soft:#4a9b4a;
  --c-gold:#d4af37;--c-gold-soft:#e6c869;
  --c-bg:#f5f5f5;--c-bg-deep:#ffffff;--c-fg:#111827;--c-fg-soft:#4b5563;
  --glass-bg:rgba(255,255,255,0.82);--glass-border:rgba(0,0,0,0.08);
  --glass-shadow:0 4px 24px rgba(0,0,0,0.06),0 1px 3px rgba(0,0,0,0.04);
  --glass-blur:20px;
  --ease-cinematic:cubic-bezier(0.22,1,0.36,1);
}
html.dark{
  --c-bg:#0a0f0a;--c-bg-deep:#050805;--c-fg:#f4f7f1;--c-fg-soft:#b8c2b3;
  --glass-bg:rgba(10,15,10,0.55);--glass-border:rgba(212,175,55,0.18);
  --glass-shadow:0 4px 24px rgba(0,0,0,0.35),0 1px 3px rgba(0,0,0,0.3);
}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;background:var(--c-bg);color:var(--c-fg);line-height:1.6;-webkit-font-smoothing:antialiased;min-height:100vh;overflow-x:hidden;transition:background-color .25s,color .25s;}
::selection{background:#008000;color:#fff;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-track{background:var(--c-bg);}
::-webkit-scrollbar-thumb{background:var(--c-primary);border-radius:999px;border:2px solid var(--c-bg);}
::-webkit-scrollbar-thumb:hover{background:var(--c-primary-deep);}
.glass{background:var(--glass-bg);-webkit-backdrop-filter:blur(20px) saturate(150%);backdrop-filter:blur(20px) saturate(150%);border:1px solid var(--glass-border);box-shadow:var(--glass-shadow);}
.wu-display{font-family:'Inter',system-ui,sans-serif;letter-spacing:-0.01em;}
/* CONTAINERS (three, per source site - do not unify) */
.wu-container{margin:0 auto;width:90%;max-width:1560px;}
@media(min-width:1024px){.wu-container{width:85%;}}
.wu-headin{margin:0 auto;width:100%;max-width:80rem;padding:0 1rem;}
@media(min-width:640px){.wu-headin{padding:0 1.5rem;}}
@media(min-width:1024px){.wu-headin{padding:0 2rem;}}
.wu-footin{width:85%;max-width:1800px;margin:0 auto;}
/* ANIMATIONS */
@keyframes wuFadeUp{from{opacity:0;transform:translateY(18px);}to{opacity:1;transform:translateY(0);}}
.wu-fadeUp{animation:wuFadeUp .8s var(--ease-cinematic) both;}
@keyframes wuShimmer{0%{background-position:-400px 0;}100%{background-position:400px 0;}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;}}
body.wu-noscroll{overflow:hidden;}

/* ============ HEADER ============ */
#wu-header{position:fixed;top:0;left:0;right:0;z-index:50;background:var(--c-bg);border-bottom:1px solid var(--glass-border);padding:.75rem 0;transition:background .3s,padding .3s,box-shadow .3s;}
#wu-header.scrolled{background:var(--glass-bg);-webkit-backdrop-filter:blur(20px) saturate(150%);backdrop-filter:blur(20px) saturate(150%);padding:.5rem 0;box-shadow:0 10px 15px -3px rgba(0,0,0,0.05),0 4px 6px -4px rgba(0,0,0,0.05);}
.wu-headspace{height:4rem;}
.wu-headrow{display:flex;align-items:center;justify-content:space-between;gap:.75rem;}
.wu-headrow > a{flex-shrink:0;display:flex;align-items:center;}
.wu-logo-img{height:2.5rem;width:auto;object-fit:contain;}
@media(min-width:640px){.wu-logo-img{height:2.75rem;}}
.wu-logo-text{font-size:1.35rem;font-weight:800;letter-spacing:-.02em;color:var(--c-primary);white-space:nowrap;}
.wu-nav{display:none;align-items:center;gap:.125rem;}
@media(min-width:768px){.wu-nav{display:flex;}}
.wu-nav-item{position:relative;}
.wu-nav-link{position:relative;display:flex;align-items:center;gap:.25rem;border-radius:9999px;padding:.5rem 1rem;font-size:.875rem;font-weight:500;color:var(--c-fg);transition:color .15s,background .15s;white-space:nowrap;}
@media(min-width:768px) and (max-width:1023px){.wu-nav-link{padding:.45rem .5rem;font-size:.78rem;gap:.15rem;}.wu-logo-img{height:2.25rem;}}
.wu-nav-link:hover{color:var(--c-primary);background:rgba(0,128,0,0.06);}
.wu-nav-link.active{color:var(--c-primary);}
.wu-nav-link.active:after{content:'';position:absolute;left:.75rem;right:.75rem;bottom:-2px;height:2px;border-radius:9999px;background:var(--c-primary);}
.wu-nav-link svg{transition:transform .2s;}
.wu-nav-item:hover .wu-nav-link svg,.wu-nav-item:focus-within .wu-nav-link svg{transform:rotate(180deg);}
.wu-dd{position:absolute;left:0;top:100%;margin-top:.5rem;min-width:180px;border-radius:1rem;padding:.5rem;background:var(--glass-bg);-webkit-backdrop-filter:blur(20px) saturate(150%);backdrop-filter:blur(20px) saturate(150%);border:1px solid var(--glass-border);box-shadow:0 20px 25px -5px rgba(0,0,0,0.1),0 8px 10px -6px rgba(0,0,0,0.1);opacity:0;visibility:hidden;transform:translateY(6px);transition:opacity .18s,transform .18s,visibility .18s;z-index:60;}
.wu-nav-item:hover .wu-dd,.wu-nav-item:focus-within .wu-dd{opacity:1;visibility:visible;transform:translateY(0);}
.wu-dd a{display:block;border-radius:.75rem;padding:.5rem .75rem;font-size:.875rem;color:var(--c-fg);transition:background .12s,color .12s;}
.wu-dd a:hover{background:rgba(0,128,0,0.08);color:var(--c-primary);}
.wu-dd .all{color:var(--c-primary);font-weight:600;}
.wu-dd .div{height:1px;margin:.35rem .5rem;background:var(--glass-border);}
.wu-head-actions{display:flex;align-items:center;gap:.375rem;}
.wu-icon-btn{display:flex;align-items:center;justify-content:center;width:2.4rem;height:2.4rem;border-radius:9999px;border:none;cursor:pointer;background:transparent;color:var(--c-fg);transition:background .15s,color .15s;}
.wu-icon-btn:hover{background:rgba(0,128,0,0.08);color:var(--c-primary);}
.wu-hamburger{display:flex;}
@media(min-width:768px){.wu-hamburger{display:none;}}

/* ============ MOBILE FULL-SCREEN MENU ============ */
#wu-mm{position:fixed;inset:0;z-index:70;background:var(--c-bg);background-image:radial-gradient(60% 40% at 15% 0%,rgba(0,128,0,0.07),transparent),radial-gradient(50% 35% at 100% 100%,rgba(212,175,55,0.06),transparent);display:flex;flex-direction:column;opacity:0;visibility:hidden;transform:translateY(12px);transition:opacity .3s var(--ease-cinematic),transform .3s var(--ease-cinematic),visibility .3s;}
#wu-mm.open{opacity:1;visibility:visible;transform:translateY(0);}
.wu-mm-top{display:flex;align-items:center;justify-content:space-between;padding:.85rem 1.25rem;border-bottom:1px solid var(--glass-border);}
.wu-mm-close{display:inline-flex;align-items:center;gap:.4rem;border:1px solid var(--glass-border);background:var(--c-bg-deep);color:var(--c-fg);border-radius:9999px;padding:.45rem 1rem;font-size:.8125rem;font-weight:600;cursor:pointer;font-family:inherit;}
.wu-mm-close:hover{border-color:rgba(0,128,0,0.4);color:var(--c-primary);}
.wu-mm-nav{flex:1;overflow-y:auto;padding:1rem 1.25rem 2rem;}
.wu-mm-row{display:flex;align-items:center;gap:.4rem;margin-bottom:.4rem;}
.wu-mm-nav > *{opacity:0;transform:translateY(10px);}
#wu-mm.open .wu-mm-nav > *{animation:wuFadeUp .55s var(--ease-cinematic) forwards;}
#wu-mm.open .wu-mm-nav > :nth-child(1){animation-delay:0ms;}
#wu-mm.open .wu-mm-nav > :nth-child(2){animation-delay:80ms;}
#wu-mm.open .wu-mm-nav > :nth-child(3){animation-delay:160ms;}
#wu-mm.open .wu-mm-nav > :nth-child(4){animation-delay:240ms;}
#wu-mm.open .wu-mm-nav > :nth-child(5){animation-delay:320ms;}
#wu-mm.open .wu-mm-nav > :nth-child(6){animation-delay:400ms;}
#wu-mm.open .wu-mm-nav > :nth-child(7){animation-delay:480ms;}
.wu-mm-link{flex:1;display:flex;align-items:center;gap:.8rem;border-radius:1rem;padding:.7rem .8rem;font-size:1.05rem;font-weight:600;color:var(--c-fg);}
.wu-mm-link:hover{background:rgba(0,128,0,0.07);}
.wu-mm-blob{display:flex;align-items:center;justify-content:center;width:2.4rem;height:2.4rem;border-radius:.85rem;color:#fff;flex-shrink:0;}
.wu-mm-tog{display:flex;align-items:center;justify-content:center;width:2.6rem;height:2.6rem;border-radius:.85rem;border:1px solid var(--glass-border);background:transparent;color:var(--c-fg-soft);cursor:pointer;transition:transform .2s;}
.wu-acc.open .wu-mm-tog{transform:rotate(180deg);color:var(--c-primary);}
.wu-acc{margin-bottom:.4rem;}
.wu-acc .wu-mm-row{margin-bottom:0;}
.wu-acc-body{display:none;flex-wrap:wrap;gap:.45rem;padding:.6rem .5rem .8rem 3.6rem;}
.wu-acc.open .wu-acc-body{display:flex;}
.wu-acc-pill{display:inline-flex;border:1px solid var(--glass-border);border-radius:9999px;padding:.375rem .875rem;font-size:.75rem;font-weight:500;color:var(--c-fg-soft);transition:color .12s,border-color .12s,background .12s;}
.wu-mm-foot{position:sticky;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.85rem 1.25rem;border-top:1px solid var(--glass-border);background:var(--glass-bg);-webkit-backdrop-filter:blur(20px);backdrop-filter:blur(20px);}
.wu-mm-foot span{font-size:.8rem;color:var(--c-fg-soft);}
.wu-mm-theme{display:inline-flex;align-items:center;gap:.5rem;border:1px solid var(--glass-border);background:var(--c-bg-deep);color:var(--c-fg);border-radius:9999px;padding:.5rem 1.1rem;font-size:.8125rem;font-weight:600;cursor:pointer;font-family:inherit;}
.wu-mm-theme:hover{border-color:rgba(0,128,0,0.4);color:var(--c-primary);}

/* ============ SEARCH OVERLAY ============ */
#wu-search{position:fixed;inset:0;z-index:80;opacity:0;visibility:hidden;transition:opacity .25s,visibility .25s;}
#wu-search.open{opacity:1;visibility:visible;}
#wu-search .bg{position:absolute;inset:0;background:rgba(3,10,4,0.55);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);}
#wu-search .panel{position:relative;margin:9vh auto 0;width:min(760px,92%);border-radius:1.25rem;background:var(--glass-bg);-webkit-backdrop-filter:blur(20px) saturate(150%);backdrop-filter:blur(20px) saturate(150%);border:1px solid var(--glass-border);box-shadow:0 25px 50px -12px rgba(0,0,0,0.35);transform:translateY(-10px);transition:transform .25s var(--ease-cinematic);overflow:hidden;}
#wu-search.open .panel{transform:translateY(0);}
.wu-search-in{padding:1.1rem 1.1rem 1.25rem;}
.wu-search-row{display:flex;align-items:center;gap:.6rem;}
.wu-search-field{position:relative;flex:1;display:flex;align-items:center;gap:.6rem;border:1px solid var(--glass-border);border-radius:9999px;padding:.7rem 1.1rem;background:var(--c-bg-deep);color:var(--c-fg-soft);}
.wu-search-field:focus-within{border-color:rgba(0,128,0,0.45);}
.wu-search-field input{flex:1;border:none;outline:none;background:transparent;color:var(--c-fg);font-size:1rem;font-family:inherit;}
.wu-search-x{display:flex;align-items:center;justify-content:center;width:2.6rem;height:2.6rem;border-radius:9999px;border:1px solid var(--glass-border);background:transparent;color:var(--c-fg-soft);cursor:pointer;}
.wu-search-x:hover{color:var(--c-primary);border-color:rgba(0,128,0,0.4);}
.wu-search-body{margin-top:1rem;max-height:56vh;overflow-y:auto;}
.wu-search-state{text-align:center;padding:2.2rem 1rem;color:var(--c-fg-soft);}
.wu-search-state .ic{display:inline-flex;align-items:center;justify-content:center;width:4rem;height:4rem;border-radius:9999px;background:rgba(0,128,0,0.09);color:var(--c-primary);margin-bottom:.9rem;}
.wu-search-state h3{color:var(--c-fg);font-size:1.05rem;margin-bottom:.25rem;}
.wu-search-state p{font-size:.875rem;}
.wu-search-lbl{font-size:.7rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--c-primary);margin:.25rem 0 .6rem;}
.wu-recent{display:flex;flex-wrap:wrap;gap:.5rem;}
.wu-recent button{border:1px solid var(--glass-border);background:var(--c-bg-deep);color:var(--c-fg);border-radius:9999px;padding:.45rem 1rem;font-size:.8125rem;cursor:pointer;font-family:inherit;}
.wu-recent button:hover{border-color:rgba(0,128,0,0.45);color:var(--c-primary);}
.wu-sug-list{display:flex;flex-direction:column;gap:.5rem;}
.wu-sug{display:flex;gap:.8rem;border-radius:1rem;padding:.55rem;transition:background .12s;}
.wu-sug:hover{background:rgba(0,128,0,0.06);}
.wu-sug-img{width:5.2rem;height:3.6rem;border-radius:.7rem;overflow:hidden;flex-shrink:0;background:linear-gradient(135deg,#0c4a1a,#3aa15a);}
.wu-sug-img img{width:100%;height:100%;object-fit:cover;}
.wu-sug-b{min-width:0;}
.wu-sug-meta{display:flex;gap:.6rem;align-items:center;font-size:.7rem;color:var(--c-fg-soft);margin-bottom:.15rem;}
.wu-sug-cat{color:var(--c-primary);font-weight:600;}
.wu-sug h4{font-size:.9rem;font-weight:600;color:var(--c-fg);line-height:1.35;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}
.wu-sug p{font-size:.78rem;color:var(--c-fg-soft);overflow:hidden;display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;}
.wu-search-go{display:inline-flex;align-items:center;gap:.4rem;margin-top:.9rem;border:none;border-radius:9999px;background:var(--c-primary);color:#fff;padding:.6rem 1.2rem;font-size:.85rem;font-weight:600;cursor:pointer;font-family:inherit;}
.wu-search-go:hover{background:var(--c-primary-deep);}
.wu-spin{display:inline-block;width:1rem;height:1rem;border:2px solid rgba(0,128,0,0.25);border-top-color:var(--c-primary);border-radius:50%;animation:wuSpin .7s linear infinite;}
@keyframes wuSpin{to{transform:rotate(360deg);}}

/* ============ HEROES (shared bits) ============ */
.wu-ov{position:absolute;inset:0;background:linear-gradient(to bottom,rgba(0,0,0,0.55),rgba(0,0,0,0.35) 50%,rgba(0,0,0,0.7));}
.wu-fadedown{position:absolute;left:0;right:0;bottom:0;height:6rem;background:linear-gradient(to bottom,transparent,var(--c-bg));}
.wu-hero-on-dark{color:#fff;text-shadow:0 2px 18px rgba(0,0,0,0.55);}
.wu-hero-sub-on-dark{color:rgba(255,255,255,0.85);}
.wu-herobg{position:absolute;inset:0;background-size:cover;background-position:center;background-image:linear-gradient(135deg,#031a0d,#0c4a1a,#3aa15a);}

/* HOMEPAGE HERO */
.wu-hero{position:relative;margin-top:-4rem;min-height:100vh;min-height:100svh;display:flex;align-items:center;overflow:hidden;}
.wu-hero-inner{position:relative;z-index:2;width:90%;max-width:1560px;margin:0 auto;padding:7rem 0 6rem;}
@media(min-width:1024px){.wu-hero-inner{width:85%;}}
.wu-hero-pill{display:inline-flex;align-items:center;gap:.5rem;border:1px solid rgba(255,255,255,0.25);background:rgba(255,255,255,0.1);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);border-radius:9999px;padding:.45rem 1.1rem;font-size:.75rem;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:#fff;margin-bottom:1.4rem;}
.wu-hero-dot{width:.5rem;height:.5rem;border-radius:9999px;background:#4ade80;box-shadow:0 0 10px #4ade80;}
.wu-hero-title{font-size:clamp(2.4rem,6vw,4.6rem);font-weight:900;line-height:1.05;letter-spacing:-.02em;color:#fff;text-shadow:0 2px 20px rgba(0,0,0,0.55);max-width:18ch;text-wrap:balance;}
.wu-hero-title .gold{color:var(--c-gold-soft);}
.wu-hero-sub{margin-top:1.1rem;font-size:clamp(1rem,1.6vw,1.25rem);color:rgba(255,255,255,0.85);max-width:56ch;}
.wu-hero-cta{display:flex;flex-wrap:wrap;gap:.8rem;margin-top:2rem;}
.wu-cta-primary{display:inline-flex;align-items:center;gap:.5rem;border-radius:9999px;background:var(--c-primary);color:#fff;padding:.8rem 1.6rem;font-size:.9rem;font-weight:700;box-shadow:0 8px 24px rgba(0,128,0,0.4);transition:background .15s,transform .15s;}
.wu-cta-primary:hover{background:var(--c-primary-deep);transform:translateY(-1px);}
.wu-cta-secondary{display:inline-flex;align-items:center;gap:.5rem;border-radius:9999px;border:1px solid rgba(255,255,255,0.35);background:rgba(255,255,255,0.08);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);color:#fff;padding:.8rem 1.6rem;font-size:.9rem;font-weight:600;transition:background .15s;}
.wu-cta-secondary:hover{background:rgba(255,255,255,0.18);}

/* ============ SECTIONS / HEADINGS ============ */
.wu-section{padding:2.5rem 0;}
@media(min-width:768px){.wu-section{padding:3.5rem 0;}}
.wu-sechead{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:2.5rem;}
.wu-sechead-l{display:flex;flex-direction:column;gap:.375rem;}
.wu-eyebrow{display:inline-flex;align-items:center;gap:.4rem;font-size:11px;font-weight:600;letter-spacing:.14em;text-transform:uppercase;color:var(--c-primary);}
.wu-sectitle{font-size:1.875rem;font-weight:900;line-height:1;letter-spacing:-.025em;color:var(--c-fg);}
@media(min-width:640px){.wu-sectitle{font-size:2.25rem;}}
.wu-viewall{display:inline-flex;align-items:center;gap:.4rem;border:1.5px solid var(--c-primary);border-radius:9999px;padding:.5rem 1rem;font-size:.875rem;font-weight:600;color:var(--c-primary);transition:background .15s,color .15s;white-space:nowrap;}
.wu-viewall:hover{background:var(--c-primary);color:#fff;}
.wu-grid{display:grid;grid-template-columns:1fr;gap:1.5rem;}
@media(min-width:640px){.wu-grid{grid-template-columns:repeat(2,1fr);}}
@media(min-width:1024px){.wu-grid{grid-template-columns:repeat(3,1fr);}}
.wu-empty{text-align:center;color:var(--c-fg-soft);padding:3rem 1rem;}
.wu-count{margin-bottom:1.5rem;}
.wu-count h2{font-size:1.5rem;font-weight:900;letter-spacing:-.02em;}
.wu-count p{color:var(--c-fg-soft);font-size:.9rem;}

/* HOMEPAGE POST CARD (LatestPostCard) */
.wu-card{position:relative;display:flex;height:100%;flex-direction:column;overflow:hidden;border-radius:1rem;background:var(--c-bg-deep);box-shadow:0 2px 12px rgba(0,0,0,0.07),0 0 0 1px var(--glass-border);transition:box-shadow .3s var(--ease-cinematic),transform .3s var(--ease-cinematic);}
.wu-card:hover{box-shadow:0 16px 40px rgba(0,128,0,0.14),0 0 0 1px var(--glass-border);}
.wu-card-img{position:relative;aspect-ratio:16/9;overflow:hidden;background:linear-gradient(135deg,#0c4a1a,#3aa15a,#d4af37);}
.wu-card-img img{width:100%;height:100%;object-fit:cover;transition:transform .6s var(--ease-cinematic);}
.wu-card:hover .wu-card-img img{transform:scale(1.15);}
.wu-no-img{width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0c4a1a,#3aa15a,#d4af37);color:rgba(255,255,255,0.9);font-size:2rem;font-weight:900;}
.wu-card-badge{position:absolute;top:.75rem;left:.75rem;border-radius:9999px;padding:.3rem .8rem;font-size:11px;font-weight:600;color:#fff;background:linear-gradient(135deg,#006000,#3a9e3a);box-shadow:0 2px 8px rgba(0,0,0,0.25);}
.wu-card-badge.animals{background:linear-gradient(135deg,#1a5c34,#2e9958);}
.wu-card-badge.birds{background:linear-gradient(135deg,#0a4a9c,#1a72d8);}
.wu-card-body{display:flex;flex:1;flex-direction:column;gap:.6rem;padding:1rem 1.25rem 1.25rem;}
.wu-card-title{font-size:1.25rem;font-weight:700;line-height:1.375;letter-spacing:-.01em;color:var(--c-fg);overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;transition:color .15s;}
.wu-card:hover .wu-card-title{color:var(--c-primary);}
.wu-card-excerpt{font-size:.95rem;color:var(--c-fg-soft);overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;}
.wu-card-foot{display:flex;align-items:center;justify-content:space-between;gap:.75rem;margin-top:auto;padding-top:.75rem;border-top:1px solid var(--glass-border);font-size:.78rem;color:var(--c-fg-soft);}

/* GLASS POST CARD (related / category grids) */
.wu-gcard{position:relative;display:flex;height:100%;flex-direction:column;overflow:hidden;border-radius:1rem;background:var(--glass-bg);-webkit-backdrop-filter:blur(20px) saturate(150%);backdrop-filter:blur(20px) saturate(150%);border:1px solid var(--glass-border);box-shadow:var(--glass-shadow);transition:transform .3s var(--ease-cinematic),border-color .3s,box-shadow .3s;}
.wu-gcard:hover{transform:scale(1.02);border-color:rgba(0,128,0,0.4);box-shadow:0 25px 50px -12px rgba(0,0,0,0.25);}
.wu-gcard-img{position:relative;aspect-ratio:16/10;overflow:hidden;background:linear-gradient(135deg,#0c4a1a,#3aa15a);}
.wu-gcard-img img{width:100%;height:100%;object-fit:cover;}
.wu-gcard-pill{position:absolute;top:.75rem;left:.75rem;border-radius:9999px;background:rgba(0,0,0,0.4);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);padding:.25rem .625rem;font-size:.75rem;color:#fff;}
.wu-gcard-pill.featured{background:rgba(212,175,55,0.9);color:#1a1208;font-weight:700;}
.wu-gcard-body{display:flex;flex:1;flex-direction:column;gap:.75rem;padding:1.5rem;}
.wu-gcard-title{font-size:1.1rem;font-weight:700;line-height:1.4;color:var(--c-fg);overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}
.wu-gcard-meta{font-size:.78rem;color:var(--c-fg-soft);}
.wu-gcard-cta{display:inline-flex;align-self:flex-start;margin-top:auto;border-radius:9999px;background:rgba(0,128,0,0.1);color:var(--c-primary);padding:.4rem 1rem;font-size:.8rem;font-weight:600;}

/* EXPLORE CATEGORY CARDS */
.wu-cats-head{text-align:center;margin-bottom:2.5rem;}
.wu-cats-head h2{font-size:1.875rem;font-weight:900;letter-spacing:-.025em;}
@media(min-width:640px){.wu-cats-head h2{font-size:2.25rem;}}
@media(min-width:768px){.wu-cats-head h2{font-size:3rem;}}
.wu-cats-head p{margin-top:.5rem;color:var(--c-fg-soft);}
.wu-cats-grid{display:grid;grid-template-columns:1fr;gap:1.5rem;}
@media(min-width:640px){.wu-cats-grid{grid-template-columns:repeat(2,1fr);}}
@media(min-width:1024px){.wu-cats-grid{grid-template-columns:repeat(3,1fr);}}
.wu-catcard{position:relative;display:block;aspect-ratio:16/10;border-radius:1rem;overflow:hidden;transition:transform .3s var(--ease-cinematic),box-shadow .3s;}
.wu-catcard:hover{transform:translateY(-4px);box-shadow:0 20px 45px rgba(0,0,0,0.28);}
.wu-catcard .ov{position:absolute;inset:0;background:linear-gradient(to top,rgba(0,0,0,0.55),transparent 55%);}
.wu-catcard .info{position:absolute;left:1.25rem;right:1.25rem;bottom:1.25rem;display:flex;align-items:flex-end;justify-content:space-between;gap:.75rem;}
.wu-catcard .info h3{font-size:1.25rem;font-weight:900;color:#fff;letter-spacing:-.01em;}
.wu-catcard .pill{display:inline-flex;align-items:center;gap:.3rem;border-radius:9999px;padding:.35rem .9rem;font-size:.75rem;font-weight:700;color:#04120a;background:#fff;white-space:nowrap;}

/* PAGINATION */
.wu-pager{display:flex;align-items:center;justify-content:center;gap:.6rem;margin:2.5rem 0 1rem;flex-wrap:wrap;}
.wu-pager a{display:inline-flex;align-items:center;gap:.35rem;border:1px solid var(--glass-border);background:var(--c-bg-deep);border-radius:9999px;padding:.55rem 1.2rem;font-size:.875rem;font-weight:600;color:var(--c-fg);transition:background .15s,color .15s,border-color .15s;}
.wu-pager a:hover{border-color:var(--c-primary);color:var(--c-primary);}
.wu-pager a.solid{background:var(--c-primary);border-color:var(--c-primary);color:#fff;}
.wu-pager a.solid:hover{background:var(--c-primary-deep);}

/* ============ CATEGORY / LABEL HERO + FILTER BAR ============ */
.wu-cathero{position:relative;margin-top:-4rem;height:88vh;min-height:640px;display:flex;align-items:center;justify-content:center;overflow:hidden;text-align:center;}
.wu-cathero .wu-fadedown{height:6rem;}
.wu-cathero-inner{position:relative;z-index:2;padding:0 1rem;max-width:60rem;}
.wu-cathero-pill{display:inline-flex;align-items:center;gap:.5rem;border:1px solid rgba(255,255,255,0.2);background:rgba(255,255,255,0.1);-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);border-radius:9999px;padding:.4rem 1.1rem;font-size:.72rem;font-weight:600;letter-spacing:.18em;text-transform:uppercase;color:#fff;margin-bottom:1.2rem;}
.wu-cathero-title{font-size:3rem;font-weight:900;letter-spacing:-.02em;line-height:1.02;}
@media(min-width:640px){.wu-cathero-title{font-size:3.75rem;}}
@media(min-width:768px){.wu-cathero-title{font-size:4.5rem;}}
.wu-cathero-sub{margin-top:1rem;font-size:1.05rem;}
.wu-catbar{border-bottom:1px solid var(--glass-border);background:var(--c-bg);}
.wu-catbar-inner{margin:0 auto;width:90%;max-width:1560px;display:flex;gap:.6rem;overflow-x:auto;padding:1rem 0;scrollbar-width:none;}
@media(min-width:1024px){.wu-catbar-inner{width:85%;}}
.wu-catbar-inner::-webkit-scrollbar{display:none;}
.wu-chip{display:inline-flex;flex-shrink:0;border:1px solid var(--glass-border);background:var(--c-bg-deep);border-radius:9999px;padding:.5rem 1.25rem;font-size:.875rem;font-weight:500;color:var(--c-fg);transition:background .15s,color .15s;white-space:nowrap;}
.wu-chip:hover{background:var(--glass-border);}
.wu-chip.active{background:var(--c-primary);border-color:var(--c-primary);color:#fff;font-weight:600;}

/* ============ POST / ARTICLE PAGE ============ */
#wu-progress{position:fixed;left:0;top:0;z-index:60;height:4px;width:0;transform-origin:left;background:var(--c-primary);}
.wu-arth{position:relative;margin-top:-4rem;display:flex;height:88vh;min-height:640px;align-items:flex-end;overflow:hidden;}
.wu-arth-bg{position:absolute;inset:0;background-size:cover;background-position:center;background-image:linear-gradient(135deg,#031a0d,#0c4a1a,#3aa15a);}
.wu-arth .wu-fadedown{height:4rem;}
.wu-arth-inner{position:relative;z-index:2;width:90%;max-width:1560px;margin:0 auto;padding:5rem 0 3.5rem;}
@media(min-width:640px){.wu-arth-inner{padding:6rem 0 4rem;}}
@media(min-width:1024px){.wu-arth-inner{width:85%;}}
.wu-arth-back{display:inline-flex;align-items:center;gap:.45rem;border:1px solid var(--glass-border);background:var(--glass-bg);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border-radius:9999px;padding:.5rem 1rem;font-size:.875rem;color:var(--c-fg);margin-bottom:1.2rem;transition:border-color .15s,color .15s;}
.wu-arth-back:hover{border-color:rgba(0,128,0,0.4);color:var(--c-primary);}
.wu-arth-cats{display:flex;flex-wrap:wrap;gap:.5rem;margin-bottom:1rem;}
.wu-arth-cat{display:inline-flex;align-items:center;gap:.35rem;background:#008000;border-radius:9999px;padding:.375rem .875rem;font-size:.75rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:#fff;box-shadow:0 2px 12px rgba(0,128,0,0.4);}
.wu-arth-cat.featured{background:rgba(212,175,55,0.9);color:#1a1208;box-shadow:0 2px 12px rgba(212,175,55,0.4);}
.wu-arth-title{font-size:1.875rem;font-weight:900;line-height:1.05;letter-spacing:-.02em;color:#fff;text-shadow:0 2px 18px rgba(0,0,0,0.55);max-width:24ch;text-wrap:balance;}
@media(min-width:640px){.wu-arth-title{font-size:2.25rem;}}
@media(min-width:768px){.wu-arth-title{font-size:3rem;}}
@media(min-width:1024px){.wu-arth-title{font-size:3.75rem;}}
.wu-arth-meta{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1.3rem;}
.wu-meta-chip{display:inline-flex;align-items:center;gap:.4rem;border:1px solid var(--glass-border);background:var(--glass-bg);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border-radius:9999px;padding:.375rem .875rem;font-size:.75rem;color:var(--c-fg);}
.wu-meta-chip svg{color:var(--c-primary);}
.wu-arth-actions{display:flex;gap:.5rem;margin-top:1rem;}
.wu-act-pill{display:inline-flex;align-items:center;gap:.4rem;border:1px solid var(--glass-border);background:var(--glass-bg);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border-radius:9999px;padding:.45rem 1rem;font-size:.8rem;font-weight:600;color:var(--c-fg);cursor:pointer;font-family:inherit;transition:border-color .15s,color .15s;}
.wu-act-pill:hover{border-color:rgba(0,128,0,0.45);color:var(--c-primary);}
.wu-act-pill.saved{border-color:rgba(212,175,55,0.6);color:var(--c-gold);}
/* BODY GRID */
.wu-artwrap{margin:0 auto;width:100%;max-width:1560px;padding-top:1.5rem;}
@media(min-width:640px){.wu-artwrap{width:90%;}}
@media(min-width:1024px){.wu-artwrap{width:85%;}}
.wu-artgrid{display:grid;grid-template-columns:1fr;gap:.75rem;}
@media(min-width:640px){.wu-artgrid{gap:1.5rem;}}
@media(min-width:1024px){.wu-artgrid{grid-template-columns:220px 1fr;gap:2rem;}}
.wu-artgrid.no-toc{grid-template-columns:1fr;}
.wu-toc-side{display:none;}
@media(min-width:1024px){.wu-toc-side{display:block;}.wu-artgrid.no-toc .wu-toc-side{display:none;}}
.wu-toc-box{position:sticky;top:6rem;border:1px solid var(--glass-border);border-radius:1rem;background:var(--c-bg-deep);padding:1.1rem 1rem;}
.wu-toc-head{display:flex;align-items:center;gap:.5rem;margin-bottom:.8rem;}
.wu-toc-head .bar{display:inline-block;width:.3rem;height:1.1rem;border-radius:9999px;background:var(--c-primary);}
.wu-toc-head h3{font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:var(--c-fg);}
.wu-toc-list{list-style:none;max-height:60vh;overflow-y:auto;}
.wu-toc-list a{display:block;border-left:2px solid transparent;padding:.4rem .7rem;font-size:.82rem;color:var(--c-fg-soft);border-radius:0 .5rem .5rem 0;transition:color .12s,background .12s,border-color .12s;}
.wu-toc-list a:hover{color:var(--c-primary);}
.wu-toc-list a.active{border-left-color:#008000;background:rgba(0,128,0,0.1);color:#008000;font-weight:600;}
.wu-toc-list a.h3{padding-left:1.4rem;font-size:.78rem;}
.wu-artcard{border-top:1px solid var(--glass-border);border-bottom:1px solid var(--glass-border);background:var(--c-bg-deep);padding:1.5rem 1rem;margin-bottom:1.25rem;transition:box-shadow .3s;}
@media(min-width:640px){.wu-artcard{border:1px solid var(--glass-border);border-radius:1rem;padding:2rem;}}
.wu-artcard:hover{box-shadow:0 12px 40px rgba(212,175,55,0.10);}
/* .post-body prose (verbatim port) */
.post-body{font-size:1rem;line-height:1.85;color:var(--c-fg);word-wrap:break-word;}
@media(min-width:640px){.post-body{font-size:1.125rem;}}
.post-body > * + *{margin-top:0.95em;}
.post-body h1{font-size:1.95em;font-weight:800;line-height:1.25;letter-spacing:-.01em;}
.post-body h2{font-size:1.55em;font-weight:800;line-height:1.3;letter-spacing:-.01em;border-bottom:1px solid var(--glass-border);padding-bottom:.35em;}
.post-body h3{font-size:1.22em;font-weight:700;line-height:1.35;}
.post-body h4{font-size:1.05em;font-weight:700;}
.post-body h1[id],.post-body h2[id],.post-body h3[id],.post-body h4[id]{scroll-margin-top:7rem;}
.post-body a{color:var(--c-primary);text-decoration:underline;text-underline-offset:3px;}
.post-body a:hover{color:var(--c-primary-deep);}
.post-body ul,.post-body ol{padding-left:1.4em;}
.post-body li + li{margin-top:.4em;}
.post-body blockquote{border-left:3px solid var(--c-primary);padding-left:1.1em;font-style:italic;color:var(--c-fg-soft);}
.post-body .wu-funfact{background:rgba(245,158,11,0.10);border:1px solid rgba(245,158,11,0.25);border-radius:12px;padding:1em 1.2em;}
.post-body .wu-funfact:before{content:'\2726  Fun Fact';display:block;font-weight:700;color:#d97706;font-size:.85em;letter-spacing:.06em;text-transform:uppercase;margin-bottom:.4em;font-style:normal;}
.post-body .wu-inspiration{border-left:3px solid var(--c-primary);padding-left:1.1em;font-style:italic;font-size:1.08em;color:var(--c-fg);}
.post-body .wu-story{background:linear-gradient(135deg,rgba(0,128,0,0.08),rgba(212,175,55,0.08));border:1px solid var(--glass-border);border-radius:12px;padding:1em 1.2em;}
.post-body .wu-story:before{content:'Wildlife Story';display:block;font-weight:700;color:var(--c-primary);font-size:.8em;letter-spacing:.12em;text-transform:uppercase;margin-bottom:.4em;}
.post-body code{background:var(--glass-bg);border:1px solid var(--glass-border);padding:1px 6px;border-radius:4px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.9em;}
.post-body pre{background:#0d1210;color:#e5efe5;border-radius:10px;padding:1em 1.2em;overflow-x:auto;font-size:14px;}
@media(min-width:640px){.post-body pre{font-size:16px;}}
.post-body pre code{background:transparent;border:none;padding:0;color:inherit;}
.post-body table{width:100%;border-collapse:collapse;display:block;overflow-x:auto;border-radius:10px;}
.post-body th{background:rgba(0,128,0,0.08);text-transform:uppercase;letter-spacing:.04em;font-size:.82em;text-align:left;padding:.7em .9em;border-bottom:2px solid rgba(0,128,0,0.22);}
.post-body td{padding:.65em .9em;border-bottom:1px solid var(--glass-border);}
.post-body tr:nth-child(even) td{background:rgba(0,0,0,0.025);}
html.dark .post-body tr:nth-child(even) td{background:rgba(255,255,255,0.025);}
.post-body img,.post-body video{width:100%;border-radius:12px;margin:1.2em auto;}
.post-body figure{margin:1.2em auto;}
@media(max-width:640px){.post-body figure{width:calc(100% + 1.4rem);margin-left:-.7rem;}.post-body figure img{aspect-ratio:16/10;object-fit:cover;border-radius:18px;box-shadow:0 10px 30px rgba(0,0,0,0.18);}}
.post-body figcaption{text-align:center;font-size:.85em;color:var(--c-fg-soft);margin-top:.5em;}
.post-body iframe{width:100%;aspect-ratio:16/9;border:none;border-radius:12px;margin:1.2em auto;}
.post-body mark{background:rgba(212,175,55,0.28);padding:0 .2em;border-radius:3px;}
/* TAGS */
.wu-tags{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;}
.wu-tags .lbl{font-size:.75rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--c-fg-soft);margin-right:.25rem;}
.wu-tag{display:inline-flex;border:1px solid var(--glass-border);border-radius:9999px;padding:.35rem .9rem;font-size:.78rem;color:var(--c-fg);transition:border-color .12s,color .12s;}
.wu-tag:hover{border-color:rgba(0,128,0,0.45);color:var(--c-primary);}
/* REACTIONS */
.wu-react-card{border-top:3px solid #008000!important;}
.wu-react-eyebrow{font-size:.7rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--c-primary);margin-bottom:.35rem;}
.wu-react-h{font-size:1.15rem;font-weight:800;letter-spacing:-.01em;margin-bottom:1.1rem;}
.wu-react-row{display:flex;flex-wrap:wrap;gap:.6rem;}
.wu-react-btn{display:flex;flex-direction:column;align-items:center;gap:.15rem;min-width:4.2rem;border:1px solid var(--glass-border);background:var(--c-bg-deep);border-radius:1rem;padding:.6rem .7rem;cursor:pointer;font-family:inherit;color:var(--c-fg);transition:border-color .15s,background .15s,transform .15s;}
.wu-react-btn:hover{border-color:rgba(0,128,0,0.35);}
.wu-react-btn.sel{border-color:rgba(0,128,0,0.6);background:rgba(0,128,0,0.1);}
.wu-react-btn .em{font-size:1.4rem;line-height:1;}
.wu-react-btn .lb{font-size:.68rem;font-weight:600;color:var(--c-fg-soft);}
.wu-react-btn .ct{font-size:.72rem;font-weight:700;color:var(--c-primary);min-height:1em;}
.wu-react-btn.pop .em{animation:wuPop .4s var(--ease-cinematic);}
@keyframes wuPop{0%{transform:scale(1);}40%{transform:scale(1.45);}100%{transform:scale(1);}}
.wu-react-load{color:var(--c-fg-soft);font-size:.875rem;}
/* COMMENTS */
.wu-cm-card{border-top:3px solid #d4af37!important;}
.wu-cm-eyebrow{font-size:.7rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--c-gold);margin-bottom:.35rem;}
.wu-cm-h{font-size:1.15rem;font-weight:800;letter-spacing:-.01em;margin-bottom:1.1rem;}
.wu-cm-form{display:flex;flex-direction:column;gap:.7rem;margin-bottom:1.5rem;}
.wu-cm-name,.wu-cm-ta{border:1px solid var(--glass-border);border-radius:.8rem;background:var(--c-bg);color:var(--c-fg);padding:.7rem 1rem;font-size:.9rem;font-family:inherit;outline:none;}
.wu-cm-name:focus,.wu-cm-ta:focus{border-color:rgba(212,175,55,0.55);}
.wu-cm-ta{resize:vertical;min-height:6rem;}
.wu-cm-post{align-self:flex-start;border:none;border-radius:9999px;background:#d4af37;color:#1a1208;padding:.65rem 1.5rem;font-size:.875rem;font-weight:700;cursor:pointer;font-family:inherit;transition:background .15s,transform .15s;}
.wu-cm-post:hover{background:#e6c869;transform:translateY(-1px);}
.wu-cm-post:disabled{opacity:.6;cursor:default;transform:none;}
.wu-cm-ok{border:1px solid rgba(0,128,0,0.35);background:rgba(0,128,0,0.08);border-radius:.9rem;padding:1rem 1.2rem;font-size:.9rem;color:var(--c-fg);}
.wu-cm-held{border:1px solid rgba(212,175,55,0.4);background:rgba(212,175,55,0.08);border-radius:.9rem;padding:1rem 1.2rem;font-size:.9rem;color:var(--c-fg);}
.wu-cm-list{display:flex;flex-direction:column;gap:1.1rem;}
.wu-cm-item{border:1px solid var(--glass-border);border-radius:1rem;padding:1rem 1.1rem;background:var(--c-bg);}
.wu-cm-item.reply{margin-left:2.2rem;}
@media(max-width:640px){.wu-cm-item.reply{margin-left:1.1rem;}}
.wu-cm-top{display:flex;align-items:center;gap:.7rem;margin-bottom:.5rem;}
.wu-cm-av{display:flex;align-items:center;justify-content:center;width:2.3rem;height:2.3rem;border-radius:9999px;background:linear-gradient(135deg,#008000,#4a9b4a);color:#fff;font-weight:800;font-size:.95rem;flex-shrink:0;}
.wu-cm-nm{font-size:.875rem;font-weight:700;color:var(--c-fg);}
.wu-cm-dt{font-size:.72rem;color:var(--c-fg-soft);}
.wu-cm-body{font-size:.9rem;color:var(--c-fg);white-space:pre-wrap;word-wrap:break-word;}
.wu-cm-acts{display:flex;flex-wrap:wrap;align-items:center;gap:.4rem;margin-top:.6rem;}
.wu-cmr-btn{display:inline-flex;align-items:center;gap:.25rem;border:1px solid var(--glass-border);background:transparent;border-radius:9999px;padding:.25rem .6rem;font-size:.72rem;color:var(--c-fg-soft);cursor:pointer;font-family:inherit;transition:border-color .12s,background .12s;}
.wu-cmr-btn:hover{border-color:rgba(0,128,0,0.4);}
.wu-cmr-btn.sel{border-color:rgba(0,128,0,0.55);background:rgba(0,128,0,0.1);color:var(--c-primary);}
.wu-cm-reply{border:none;background:transparent;color:var(--c-primary);font-size:.75rem;font-weight:700;cursor:pointer;font-family:inherit;margin-left:auto;}
.wu-cm-reply:hover{text-decoration:underline;}
.wu-cm-empty{color:var(--c-fg-soft);font-size:.9rem;}
/* TTS (gold) */
.wu-tts{border:1px solid rgba(212,175,55,0.35);border-radius:1rem;background:linear-gradient(135deg,rgba(212,175,55,0.10),rgba(212,175,55,0.03));padding:1rem 1.1rem;margin-bottom:1.25rem;}
.wu-tts-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;}
.wu-tts-ico{display:flex;align-items:center;justify-content:center;width:2.4rem;height:2.4rem;border-radius:.8rem;background:linear-gradient(135deg,#d4af37,#b8912a);flex-shrink:0;box-shadow:0 4px 12px rgba(212,175,55,0.4);}
.wu-tts-tt{flex:1;min-width:10rem;}
.wu-tts-tt b{display:block;font-size:.9rem;color:var(--c-fg);}
.wu-tts-tt span{display:block;font-size:.72rem;color:var(--c-fg-soft);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;max-width:34ch;}
.wu-tts-lang{position:relative;}
.wu-tts-langbtn{border:1px solid rgba(212,175,55,0.4);background:var(--c-bg-deep);color:var(--c-fg);border-radius:9999px;padding:.4rem .9rem;font-size:.75rem;font-weight:600;cursor:pointer;font-family:inherit;}
.wu-tts-langmenu{position:absolute;right:0;top:110%;z-index:30;display:none;max-height:15rem;overflow-y:auto;min-width:11rem;border:1px solid var(--glass-border);border-radius:.9rem;background:var(--c-bg-deep);box-shadow:0 20px 25px -5px rgba(0,0,0,0.15);padding:.35rem;}
.wu-tts-langmenu.open{display:block;}
.wu-tts-langmenu button{display:block;width:100%;text-align:left;border:none;background:transparent;color:var(--c-fg);border-radius:.6rem;padding:.45rem .7rem;font-size:.78rem;cursor:pointer;font-family:inherit;}
.wu-tts-langmenu button:hover{background:rgba(212,175,55,0.12);}
.wu-tts-langmenu button.sel{background:rgba(212,175,55,0.2);font-weight:700;}
.wu-tts-mute{border:none;background:transparent;font-size:1.05rem;cursor:pointer;}
.wu-tts-bar{height:.4rem;border-radius:9999px;background:rgba(212,175,55,0.18);margin:.8rem 0 .7rem;overflow:hidden;}
.wu-tts-fill{height:100%;width:0;border-radius:9999px;background:linear-gradient(90deg,#d4af37,#e6c869);transition:width .35s;}
.wu-tts-ctrls{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;}
.wu-tts-btn{display:inline-flex;align-items:center;gap:.4rem;border:none;border-radius:9999px;background:#d4af37;color:#1a1208;padding:.5rem 1.15rem;font-size:.8rem;font-weight:700;cursor:pointer;font-family:inherit;transition:background .15s;}
.wu-tts-btn:hover{background:#e6c869;}
.wu-tts-btn.amber{background:#b8912a;color:#fff;}
.wu-tts-btn.gray{background:transparent;border:1px solid var(--glass-border);color:var(--c-fg-soft);}
.wu-tts-pct{font-size:.75rem;font-weight:700;color:var(--c-gold);margin-left:auto;}
/* SHARE ROW */
.wu-share{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;margin-bottom:1.25rem;}
.wu-share-lbl{font-size:.8rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--c-fg-soft);margin-right:.25rem;}
.wu-sbtn{border:1px solid var(--glass-border);background:var(--c-bg-deep);color:var(--c-fg);border-radius:9999px;padding:.5rem 1.1rem;font-size:.8rem;font-weight:600;cursor:pointer;font-family:inherit;transition:border-color .15s,color .15s;}
.wu-sbtn:hover{border-color:rgba(0,128,0,0.5);color:var(--c-primary);}
/* RELATED */
.wu-rel{padding:2.5rem 0 1rem;}
.wu-rel-h{font-size:1.6rem;font-weight:900;letter-spacing:-.02em;margin-bottom:.35rem;}
.wu-rel-sub{color:var(--c-fg-soft);font-size:.9rem;margin-bottom:1.6rem;}

/* ============ STATIC PAGE WRAPPER ============ */
.wu-pagewrap{min-height:40vh;}

/* ============ 404 ============ */
.wu-404{display:flex;align-items:center;justify-content:center;padding:8rem 1rem 6rem;}
.wu-404-in{max-width:42rem;width:100%;text-align:center;border-radius:1.5rem;background:var(--glass-bg);-webkit-backdrop-filter:blur(20px) saturate(150%);backdrop-filter:blur(20px) saturate(150%);border:1px solid var(--glass-border);box-shadow:var(--glass-shadow);padding:3rem 2rem;}
@media(min-width:640px){.wu-404-in{padding:3rem;}}
.wu-404-eyebrow{font-size:.8rem;font-weight:800;letter-spacing:.3em;text-transform:uppercase;color:var(--c-primary);margin-bottom:.8rem;}
.wu-404-h{font-size:2.25rem;font-weight:900;letter-spacing:-.02em;margin-bottom:.7rem;}
@media(min-width:640px){.wu-404-h{font-size:3rem;}}
.wu-404-p{color:var(--c-fg-soft);max-width:34rem;margin:0 auto 1.6rem;}
.wu-404-btns{display:flex;justify-content:center;gap:.7rem;flex-wrap:wrap;margin-bottom:1.6rem;}
.wu-404-home{display:inline-flex;align-items:center;gap:.45rem;border-radius:9999px;background:var(--c-primary);color:#fff;padding:.65rem 1.4rem;font-size:.875rem;font-weight:700;box-shadow:0 10px 15px -3px rgba(0,128,0,0.35);}
.wu-404-home:hover{background:var(--c-primary-deep);}
.wu-404-back{display:inline-flex;align-items:center;gap:.45rem;border:1px solid var(--glass-border);border-radius:9999px;background:var(--c-bg-deep);color:var(--c-fg);padding:.65rem 1.4rem;font-size:.875rem;font-weight:600;}
.wu-404-card{border:1px solid var(--glass-border);border-radius:1rem;background:var(--c-bg);padding:1.1rem;max-width:22rem;margin:0 auto;}
.wu-404-card-top{display:flex;align-items:center;justify-content:center;gap:.45rem;font-size:.78rem;color:var(--c-fg-soft);}
.wu-404-card-top .dot{width:.5rem;height:.5rem;border-radius:9999px;background:var(--c-primary);animation:wuPulse 1.2s infinite;}
@keyframes wuPulse{0%,100%{opacity:1;}50%{opacity:.35;}}
.wu-404-count{font-size:2.2rem;font-weight:900;color:var(--c-primary);margin:.3rem 0;}
.wu-404-sec{font-size:.78rem;color:var(--c-fg-soft);}

/* ============ FOOTER (always dark) ============ */
#wu-footer{background:#0d1210;margin-top:6rem;border-top:1px solid rgba(255,255,255,0.07);color:rgba(255,255,255,0.56);}
.wu-foot-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 0.9fr 1.4fr;gap:2.5rem;padding:4rem 0 3.5rem;}
@media(max-width:1100px){.wu-foot-grid{grid-template-columns:repeat(3,1fr);}}
@media(max-width:700px){.wu-foot-grid{grid-template-columns:1fr;}}
.wu-foot-logo{height:53px;width:auto;max-width:192px;object-fit:contain;margin-bottom:1rem;}
.wu-foot-desc{font-size:.875rem;line-height:1.7;color:rgba(255,255,255,0.48);margin-bottom:1.2rem;}
.wu-foot-labels{display:flex;flex-wrap:wrap;gap:.4rem;}
.wu-foot-lbl{display:inline-flex;border:1px solid rgba(255,255,255,0.12);border-radius:9999px;padding:.25rem .7rem;font-size:.68rem;color:rgba(255,255,255,0.5);transition:color .12s,border-color .12s;}
.wu-foot-lbl:hover{color:#fff;border-color:rgba(255,255,255,0.35);}
.wu-foot-h{font-size:.68rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,0.35);border-bottom:1px solid rgba(255,255,255,0.07);padding-bottom:.6rem;margin-bottom:1rem;}
.wu-foot-links{list-style:none;}
.wu-foot-links li{margin-bottom:.55rem;}
.wu-foot-links a{font-size:.875rem;color:rgba(255,255,255,0.56);transition:color .12s;}
.wu-foot-links a:hover{color:#fff;}
.wu-foot-nl p{font-size:.85rem;line-height:1.65;color:rgba(255,255,255,0.48);margin-bottom:.9rem;}
.wu-nl-row{display:flex;gap:.5rem;margin-bottom:.6rem;}
.wu-nl-field{flex:1;display:flex;align-items:center;gap:.5rem;border:1px solid rgba(255,255,255,0.12);border-radius:9999px;background:rgba(255,255,255,0.05);padding:.55rem .9rem;color:rgba(255,255,255,0.5);}
.wu-nl-field input{flex:1;min-width:0;border:none;outline:none;background:transparent;color:#fff;font-size:.85rem;font-family:inherit;}
.wu-nl-btn{display:inline-flex;align-items:center;border:none;border-radius:9999px;background:var(--c-primary);color:#fff;padding:.55rem 1.2rem;font-size:.8rem;font-weight:700;cursor:pointer;white-space:nowrap;transition:background .15s;}
.wu-nl-btn:hover{background:#006700;}
.wu-nl-note{font-size:.72rem;color:rgba(255,255,255,0.35);margin-bottom:1rem;}
.wu-nl-note a{color:rgba(255,255,255,0.55);text-decoration:underline;}
.wu-foot-social{display:flex;gap:.5rem;}
.wu-foot-soc{display:flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:.6rem;border:1px solid rgba(255,255,255,0.12);color:rgba(255,255,255,0.6);transition:background .15s,color .15s,border-color .15s;}
.wu-foot-soc:hover{color:#fff;border-color:transparent;}
.wu-foot-soc.wa:hover{background:#25D366;}
.wu-foot-soc.fb:hover{background:#1877F2;}
.wu-foot-soc.ig:hover{background:#E4405F;}
.wu-foot-soc.tk:hover{background:#000;}
.wu-foot-soc.yt:hover{background:#FF0000;}
.wu-foot-bottom{border-top:1px solid rgba(255,255,255,0.06);background:rgba(0,0,0,0.2);padding:1.1rem 0;}
.wu-foot-bottom-in{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;font-size:.8rem;color:rgba(255,255,255,0.45);}
.wu-staff{display:inline-flex;border:1px solid rgba(255,255,255,0.15);border-radius:9999px;padding:.35rem 1rem;font-size:.75rem;color:rgba(255,255,255,0.55);transition:color .12s,border-color .12s;}
.wu-staff:hover{color:#fff;border-color:rgba(255,255,255,0.4);}
/* layout helper for Blogger sections we don't render */
.no-show{display:none;}

body.script:
//
/* ============ WILDLIFE UNIVERSE - theme engine ============ */
/* THEME TOGGLE */
function wuTheme(){var d=document.documentElement.classList.toggle('dark');try{localStorage.setItem('wu-theme',d?'dark':'light');}catch(e){}wuIcons(d);var m=document.getElementById('wu-themecolor');if(m)m.setAttribute('content',d?'#0a0f0a':'#f7f9f5');}
function wuIcons(d){['wu-moon','wu-sun','wu-moon2','wu-sun2'].forEach(function(id){var el=document.getElementById(id);if(!el)return;var isMoon=id.indexOf('moon')>-1;el.style.display=(isMoon?(d?'none':''):(d?'':'none'));});}
wuIcons(document.documentElement.classList.contains('dark'));
/* YEAR + asset-driven links */
(function(){var y=document.getElementById('wu-year');if(y)y.textContent=new Date().getFullYear();var s=document.getElementById('wu-staff-login');if(s&&window.WU_ASSETS&&WU_ASSETS.staffLogin)s.setAttribute('href',WU_ASSETS.staffLogin);})();
/* HEADER glass-on-scroll */
(function(){var h=document.getElementById('wu-header');if(!h)return;function upd(){h.classList.toggle('scrolled',window.scrollY>80);}window.addEventListener('scroll',upd,{passive:true});upd();})();
/* MOBILE MENU */
function wuMenu(){var m=document.getElementById('wu-mm');if(m)m.classList.add('open');document.body.classList.add('wu-noscroll');}
function wuMenuClose(){var m=document.getElementById('wu-mm');if(m)m.classList.remove('open');document.body.classList.remove('wu-noscroll');}
window.addEventListener('resize',function(){if(window.innerWidth>=768)wuMenuClose();});
function wuToggleAcc(btn){var a=btn.closest('.wu-acc');if(a)a.classList.toggle('open');}
/* SEARCH */
var wuST=null;
function wuRecent(){try{return JSON.parse(localStorage.getItem('wu-recent')||'[]');}catch(e){return [];}}
function wuAddRecent(q){if(!q)return;var r=wuRecent().filter(function(x){return x!==q;});r.unshift(q);try{localStorage.setItem('wu-recent',JSON.stringify(r.slice(0,5)));}catch(e){}}
function wuEsc(s){return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function wuSIco(){return '<svg fill="none" height="30" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" width="30"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>';}
function wuSArr(){return '<svg fill="none" height="15" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" width="15"><path d="M5 12h14M12 5l7 7-7 7"/></svg>';}
function wuSearch(){var o=document.getElementById('wu-search');if(!o)return;o.classList.add('open');document.body.classList.add('wu-noscroll');setTimeout(function(){var i=document.getElementById('wu-search-input');if(i)i.focus();},90);wuRenderRecent();}
function wuSearchClose(){var o=document.getElementById('wu-search');if(o)o.classList.remove('open');document.body.classList.remove('wu-noscroll');}
function wuSearchGo(){var i=document.getElementById('wu-search-input');var q=i?i.value.trim():'';if(q){wuAddRecent(q);window.location.href='/search?q='+encodeURIComponent(q);}}
function wuRenderRecent(){var b=document.getElementById('wu-search-body');if(!b)return;var r=wuRecent();if(!r.length){b.innerHTML='<div class="wu-search-state"><div class="ic">'+wuSIco()+'</div><h3>Start typing to search</h3><p>Find species, stories and guides across the wild</p></div>';return;}b.innerHTML='<div class="wu-search-lbl">Recent Searches</div><div class="wu-recent">'+r.map(function(q){return '<button type="button" data-rq="'+wuEsc(q)+'">'+wuEsc(q)+'</button>';}).join('')+'</div>';}
function wuDoSearch(q){var b=document.getElementById('wu-search-body'),sp=document.getElementById('wu-search-spin');if(!b)return;if(q.length<2){wuRenderRecent();return;}if(sp)sp.style.display='';
  fetch('/feeds/posts/default?q='+encodeURIComponent(q)+'&alt=json&max-results=6').then(function(r){return r.json();}).then(function(j){if(sp)sp.style.display='none';var en=(j.feed&&j.feed.entry)||[];
    if(!en.length){b.innerHTML='<div class="wu-search-state"><div class="ic">'+wuSIco()+'</div><h3>No results found</h3><p>Try different keywords or browse the categories</p></div><button class="wu-search-go" type="button" onclick="wuSearchGo()">See all results '+wuSArr()+'</button>';return;}
    var items=en.map(function(e){var c2=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';var mm=c2.match(/<img[^>]+src=["']([^"']+)["']/i);var im=mm?mm[1]:'';var u='#';var L=e.link||[];for(var i=0;i<L.length;i++){if(L[i].rel==='alternate')u=L[i].href;}var t=e.title.$t;var c=(e.category&&e.category.length)?e.category[0].term:'';var d='';try{d=new Date(e.published.$t).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}catch(x){}var sn=((e.summary&&e.summary.$t)||'').replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim().slice(0,110);
      return '<a class="wu-sug" href="'+u+'"><div class="wu-sug-img">'+(im?'<img src="'+wuEsc(im)+'" alt="" loading="lazy"/>':'')+'</div><div class="wu-sug-b"><div class="wu-sug-meta">'+(c?'<span class="wu-sug-cat">'+wuEsc(c)+'</span>':'')+'<span>'+d+'</span></div><h4>'+wuEsc(t)+'</h4><p>'+wuEsc(sn)+'</p></div></a>';}).join('');
    b.innerHTML='<div class="wu-search-lbl">Search Results</div><div class="wu-sug-list">'+items+'</div><button class="wu-search-go" type="button" onclick="wuSearchGo()">See all results for &#8220;'+wuEsc(q)+'&#8221; '+wuSArr()+'</button>';
  }).catch(function(){if(sp)sp.style.display='none';});}
(function(){var i=document.getElementById('wu-search-input');if(!i)return;
  i.addEventListener('input',function(){clearTimeout(wuST);var q=this.value.trim();wuST=setTimeout(function(){wuDoSearch(q);},300);});
  i.addEventListener('keydown',function(e){if(e.key==='Enter')wuSearchGo();});
  var b=document.getElementById('wu-search-body');if(b)b.addEventListener('click',function(e){var rq=e.target.closest&&e.target.closest('[data-rq]');if(rq){i.value=rq.getAttribute('data-rq');wuDoSearch(i.value.trim());}});
})();
document.addEventListener('keydown',function(e){if(e.key==='Escape'){wuSearchClose();wuMenuClose();}});
/* ACTIVE NAV LINK */
(function(){var links=document.querySelectorAll('.wu-nav a,.wu-mm-nav a');var here=decodeURIComponent(window.location.href);links.forEach(function(a){var h=a.getAttribute('href')||'';if(h.indexOf('/search/label/')===0){var lbl=h.replace('/search/label/','');if(here.indexOf('/search/label/'+lbl)>-1)a.classList.add('active');}});if(location.pathname==='/'||location.pathname===''){var first=document.querySelector('.wu-nav .wu-nav-link');if(first)first.classList.add('active');}})();

/* ============ SHARED TAXONOMY + FEED HELPERS ============ */
var WU_TAX=[
  {n:'Animals',hero:'heroSavanna',desc:'Mammals, reptiles, amphibians and fish - meet the animals that rule land and water.',l:['Mammals','Reptiles','Amphibians','Fish','IUCN Redlist']},
  {n:'Plants',hero:'heroCanopy',desc:'Trees, shrubs, herbs and vines - the green architects of every ecosystem on Earth.',l:['Trees','Shrubs','Herbs','Vines']},
  {n:'Birds',hero:'heroEagle',desc:'From raptors to songbirds - the feathered wonders that fill our skies.',l:['Basal','Waterfowl','Coastal','Raptors','Land','Song','IUCN Redlist']},
  {n:'Insects',hero:'heroCanopy',desc:'Invertebrates of every kind - the small creatures that keep the planet running.',l:['Porifera','Cnidaria','Platyhelminthes','Nematoda','Annelida','Mollusca','Arthropoda','Echinodermata','IUCN Redlist']},
  {n:'Posts',hero:'heroSavanna',desc:'How and why questions, tourism, conservation and feature articles from the wild.',l:['How Questions','Why Questions','Tourism','Conservation','Articles']}
];
var WU_CATGRAD={
  'Animals':['linear-gradient(145deg,#061206,#1a4a10,#3d7a28)','#5dc23a'],
  'Plants':['linear-gradient(145deg,#04120a,#0d4a2a,#22885a)','#34d17a'],
  'Birds':['linear-gradient(145deg,#050b16,#0a2a5c,#1a5cb8)','#4a9ce8'],
  'Insects':['linear-gradient(145deg,#141004,#5c4a0a,#a8871a)','#eab308'],
  'Posts':['linear-gradient(145deg,#041204,#0a4a0a,#2e8b2e)','#4ade80']
};
function wuBadgeCls(c){c=(c||'').toLowerCase();if(c==='animals')return ' animals';if(c==='birds')return ' birds';return '';}
function wuAlt(e){var L=e.link||[];for(var i=0;i<L.length;i++){if(L[i].rel==='alternate')return L[i].href;}return '#';}
function wuImg(e){var c=(e.content&&e.content.$t)||(e.summary&&e.summary.$t)||'';var m=c.match(/<img[^>]+src=["']([^"']+)["']/i);if(m)return m[1];if(e.media$thumbnail&&e.media$thumbnail.url)return e.media$thumbnail.url.replace(/\/s72-c\//,'/w640/');return '';}
function wuSnip(e){var c=(e.summary&&e.summary.$t)||(e.content&&e.content.$t)||'';var d=document.createElement('div');d.innerHTML=c.replace(/<[^>]+>/g,' ');return (d.textContent||d.innerText||'').replace(/\s+/g,' ').trim().slice(0,140);}
function wuFdate(e){try{return new Date(e.published.$t).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'});}catch(x){return '';}}
function wuCat(e){var C=e.category||[];return C.length?C[0].term:'';}
function wuTerms(e){return (e.category||[]).map(function(x){return x.term;});}
function wuCard(e,idx){var i=wuImg(e),u=wuAlt(e),t=e.title.$t,c=wuCat(e);var dl=(typeof idx==='number')?' style="animation-delay:'+(idx*95)+'ms"':'';
  return '<a class="wu-card wu-fadeUp" href="'+u+'"'+dl+'><div class="wu-card-img">'+(i?'<img src="'+wuEsc(i)+'" alt="'+wuEsc(t)+'" loading="lazy"/>':'<div class="wu-no-img">WU</div>')+(c?'<span class="wu-card-badge'+wuBadgeCls(c)+'">'+wuEsc(c)+'</span>':'')+'</div><div class="wu-card-body"><h2 class="wu-card-title">'+wuEsc(t)+'</h2><p class="wu-card-excerpt">'+wuEsc(wuSnip(e))+'&#8230;</p><div class="wu-card-foot"><span>'+wuFdate(e)+'</span><span>Wildlife Universe</span></div></div></a>';}
function wuGCard(e){var i=wuImg(e),u=wuAlt(e),t=e.title.$t,c=wuCat(e);
  return '<a class="wu-gcard" href="'+u+'"><div class="wu-gcard-img">'+(i?'<img src="'+wuEsc(i)+'" alt="'+wuEsc(t)+'" loading="lazy"/>':'')+(c?'<span class="wu-gcard-pill">'+wuEsc(c)+'</span>':'')+'</div><div class="wu-gcard-body"><h3 class="wu-gcard-title">'+wuEsc(t)+'</h3><div class="wu-gcard-meta">'+wuFdate(e)+'</div><span class="wu-gcard-cta">View Post</span></div></a>';}
function wuFeed(p){return fetch(p,{credentials:'omit'}).then(function(r){return r.json();}).then(function(j){return (j.feed&&j.feed.entry)||[];}).catch(function(){return [];});}
function wuByLabel(l,m){return wuFeed('/feeds/posts/default/-/'+encodeURIComponent(l)+'?alt=json&max-results='+m);}
function wuLblUrl(s){return '/search/label/'+encodeURIComponent(s);}
function wuHeroUrl(key){return (window.WU_ASSETS&&WU_ASSETS[key])||'';}

/* ============ FEED ENGINE: homepage / label pages / search ============ */
(function(){
var P=location.pathname, grid=document.getElementById('wu-postgrid'), pager=document.getElementById('wu-native-pager');
var ARR='<svg fill="none" height="15" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" width="15"><path d="M5 12h14M12 5l7 7-7 7"/></svg>';
var RSS='<svg fill="none" height="13" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" width="13"><path d="M4 11a9 9 0 0 1 9 9"/><path d="M4 4a16 16 0 0 1 16 16"/><circle cx="5" cy="19" r="1"/></svg>';
function secHead(eye,title,url){return '<div class="wu-sechead"><div class="wu-sechead-l"><span class="wu-eyebrow">'+RSS+' '+wuEsc(eye)+'</span><h2 class="wu-sectitle">'+wuEsc(title)+'</h2></div><a class="wu-viewall" href="'+url+'">View All '+ARR+'</a></div>';}
if(P==='/'||P===''){
  /* homepage hero bg */
  var hb=document.getElementById('wu-hero-bg');if(hb&&wuHeroUrl('heroSavanna'))hb.style.backgroundImage='url("'+wuHeroUrl('heroSavanna')+'")';
  var extra=document.getElementById('wu-home-extra');
  /* defer the heavy fetch until after native paint */
  setTimeout(function(){
    wuFeed('/feeds/posts/default?alt=json&max-results=150').then(function(en){
      if(grid&&en.length){grid.innerHTML=en.slice(0,12).map(function(e,i){return wuCard(e,i);}).join('');}
      if(pager&&en.length)pager.style.display='none';
      if(!extra)return;
      var h='';
      /* Explore Our Categories */
      var cc='';
      WU_TAX.forEach(function(t){var g=WU_CATGRAD[t.n];cc+='<a class="wu-catcard" href="'+wuLblUrl(t.n)+'" style="background:'+g[0]+'"><div class="ov"></div><div class="info"><h3>'+wuEsc(t.n)+'</h3><span class="pill" style="background:'+g[1]+';color:#04120a">Explore '+ARR+'</span></div></a>';});
      h+='<section class="wu-section"><div class="wu-container"><div class="wu-cats-head"><h2>Explore Our Categories</h2><p>Dive into the corners of the wild that fascinate you most</p></div><div class="wu-cats-grid">'+cc+'</div></div></section>';
      /* per-category rows (6 each) */
      WU_TAX.forEach(function(t){
        var ps=en.filter(function(e){return wuTerms(e).indexOf(t.n)>-1;}).slice(0,6);
        if(!ps.length)return;
        h+='<section class="wu-section"><div class="wu-container">'+secHead('Wildlife Universe',t.n,wuLblUrl(t.n))+'<div class="wu-grid">'+ps.map(function(e,i){return wuCard(e,i);}).join('')+'</div></div></section>';
      });
      extra.innerHTML=h;
    });
  },60);
}
else if(P.indexOf('/search/label/')===0){
  var label=decodeURIComponent(P.replace('/search/label/','').replace(/\/$/,''));
  var parent=null;WU_TAX.forEach(function(t){if(t.n===label||t.l.indexOf(label)>-1)parent=t;});
  var te=document.getElementById('wu-cat-title');if(te)te.textContent=label;
  var hb2=document.getElementById('wu-cathero-bg');
  if(hb2&&parent&&wuHeroUrl(parent.hero))hb2.style.backgroundImage='url("'+wuHeroUrl(parent.hero)+'")';
  var dd=document.getElementById('wu-cat-desc');
  if(dd&&parent)dd.textContent=(label===parent.n)?parent.desc:('Explore every '+label+' story in our '+parent.n+' collection.');
  /* filter pills */
  var tools=document.getElementById('wu-cat-tools');
  if(tools&&parent&&parent.l.length){var ch='<a class="wu-chip'+(label===parent.n?' active':'')+'" href="'+wuLblUrl(parent.n)+'">All Posts</a>';parent.l.forEach(function(x){ch+='<a class="wu-chip'+(label===x?' active':'')+'" href="'+wuLblUrl(x)+'">'+wuEsc(x)+'</a>';});tools.innerHTML='<div class="wu-catbar"><div class="wu-catbar-inner">'+ch+'</div></div>';}
  wuByLabel(label,60).then(function(en){
    if(grid&&en.length){grid.innerHTML=en.map(function(e){return wuGCard(e);}).join('');var cn=document.createElement('div');cn.className='wu-count';cn.innerHTML='<h2>'+wuEsc(label)+'</h2><p>'+en.length+' '+(en.length===1?'post':'posts')+' found</p>';grid.parentNode.insertBefore(cn,grid);if(pager)pager.style.display='none';}
  });
}
else if(P==='/search'){
  var q=decodeURIComponent(((location.search.match(/[?&]q=([^&]*)/)||[])[1]||'').replace(/\+/g,' '));
  var te2=document.getElementById('wu-cat-title'); if(te2)te2.textContent='Search';
  var de=document.getElementById('wu-cat-desc'); if(de)de.textContent=q?('Showing results for "'+q+'"'):'Type a search above';
  var hb3=document.getElementById('wu-cathero-bg');if(hb3&&wuHeroUrl('heroCanopy'))hb3.style.backgroundImage='url("'+wuHeroUrl('heroCanopy')+'")';
  if(q){wuFeed('/feeds/posts/default?q='+encodeURIComponent(q)+'&alt=json&max-results=30').then(function(en){
    if(grid){if(en.length){grid.innerHTML=en.map(function(e){return wuGCard(e);}).join('');var cn=document.createElement('div');cn.className='wu-count';cn.innerHTML='<h2>Search results</h2><p>'+en.length+' result'+(en.length===1?'':'s')+' for &#8220;'+wuEsc(q)+'&#8221;</p>';grid.parentNode.insertBefore(cn,grid);}else{grid.innerHTML='<p class="wu-empty">No results found for &#8220;'+wuEsc(q)+'&#8221;. Try different keywords or browse the categories.</p>';}}
    if(pager)pager.style.display='none';
  });}
}
})();

