    btn.addEventListener('click',function(){var s=saved();var i=s.indexOf(PURL);if(i>-1)s.splice(i,1);else s.push(PURL);try{localStorage.setItem('wu_saved',JSON.stringify(s));}catch(e){}render();});
    render();
