  /* TOC */
  (function(){
    var list=document.getElementById('wu-toc-list'),side=document.getElementById('wu-toc-side'); if(!list||!content) return;
    var hs=content.querySelectorAll('h2,h3');
    if(hs.length<2){ if(side)side.style.display='none'; var g0=document.querySelector('.wu-artgrid'); if(g0)g0.classList.add('no-toc'); return; }
    var items=[],cnt={};
    hs.forEach(function(h){
      var t=(h.textContent||'').trim(); if(!t) return;
      var s=t.toLowerCase().replace(/[^\w\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-')||'h';
      cnt[s]=(cnt[s]||0)+1; if(cnt[s]>1)s+='-'+cnt[s]; h.id=s;
      var li=document.createElement('li');
