      if(h.tagName==='H3')a.className='h3';
      a.addEventListener('click',function(e){e.preventDefault();var el=document.getElementById(s);if(el)window.scrollTo({top:el.getBoundingClientRect().top+window.pageYOffset-100,behavior:'smooth'});});
      li.appendChild(a); list.appendChild(li); items.push(s);
    });
    if('IntersectionObserver' in window){
      var vis={},links=list.querySelectorAll('a');
      var obs=new IntersectionObserver(function(ents){
        ents.forEach(function(en){vis[en.target.id]=en.isIntersecting;});
        var cur=null; for(var i=0;i<items.length;i++){if(vis[items[i]]){cur=items[i];break;}}
        links.forEach(function(l){l.classList.toggle('active',l.getAttribute('data-id')===cur);});
      },{rootMargin:'-90px 0px -65% 0px',threshold:0});
      hs.forEach(function(h){obs.observe(h);});
    }
  })();

  /* TTS (Web Speech, gold theme, 30-word chunks, cancel-based pause/resume) */
  (function(){
    var host=document.getElementById('wu-tts'); if(!host||!content) return;
    if(!('speechSynthesis' in window)){ host.style.display='none'; return; }
    var LANGS=[['en-US','English (US)'],['en-GB','English (UK)'],['es-ES','Spanish'],['fr-FR','French'],['de-DE','German'],['it-IT','Italian'],['pt-BR','Portuguese'],['ja-JP','Japanese'],['zh-CN','Chinese'],['ar-SA','Arabic'],['hi-IN','Hindi'],['ru-RU','Russian'],['ko-KR','Korean'],['nl-NL','Dutch'],['pl-PL','Polish'],['sv-SE','Swedish'],['sw-KE','Swahili'],['tr-TR','Turkish']];
    var SPK='<svg width="15" height="15" fill="none" stroke="#1a1208" stroke-width="2" viewBox="0 0 24 24"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.5 8.5a5 5 0 0 1 0 7"/></svg>';
    var PLAY='<svg width="13" height="13" fill="currentColor" viewBox="0 0 24 24"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
    var PAUSE='<svg width="13" height="13" fill="currentColor" viewBox="0 0 24 24"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>';
    var STOP='<svg width="13" height="13" fill="currentColor" viewBox="0 0 24 24"><rect x="5" y="5" width="14" height="14" rx="2"/></svg>';
    var voices=[]; function lv(){voices=speechSynthesis.getVoices();} lv(); if(speechSynthesis.addEventListener)speechSynthesis.addEventListener('voiceschanged',lv);
    var lang='en-US',muted=false,chunks=[],idx=0,playing=false,paused=false,fill=null,pct=null;
    function setProg(p){if(fill)fill.style.width=p+'%';if(pct)pct.textContent=p>=100?'Finished':(p>0?Math.round(p)+'%':'');}
    function plain(){var d=document.createElement('div');d.innerHTML=content.innerHTML;return (d.textContent||d.innerText||'').replace(/\s+/g,' ').trim();}
    function chunk(t){var parts=t.match(/[^.!?]*[.!?]+\s*/g)||[t];var rem=t.slice(parts.reduce(function(n,p){return n+p.length;},0)).trim();if(rem)parts.push(rem);var out=[],c='',w=0;parts.forEach(function(p){var pw=p.split(/\s+/).length;if(w+pw>30&&c){out.push(c.trim());c='';w=0;}c+=p;w+=pw;});if(c.trim())out.push(c.trim());return out;}
    function pickVoice(){return voices.filter(function(v){return v.lang===lang&&/Google|Natural/.test(v.name);})[0]||voices.filter(function(v){return v.lang.indexOf(lang.split('-')[0])===0;})[0]||voices.filter(function(v){return v.lang===lang;})[0];}
    function speak(i){ if(i>=chunks.length){playing=false;paused=false;setProg(100);render();return;} idx=i; var u=new SpeechSynthesisUtterance(chunks[i]); u.lang=lang; u.rate=0.95; u.volume=muted?0:1; var v=pickVoice(); if(v)u.voice=v; u.onend=function(){ if(paused)return; setProg(((i+1)/chunks.length)*100); setTimeout(function(){speak(i+1);},50); }; speechSynthesis.speak(u); }
    function start(){ speechSynthesis.cancel(); chunks=chunk(plain()); if(!chunks.length)return; playing=true;paused=false; render(); speak(0); }
    function pause(){ paused=true; speechSynthesis.cancel(); playing=false; render(); }
    function resume(){ paused=false;playing=true; render(); speak(idx); }
    function stop(){ speechSynthesis.cancel(); playing=false;paused=false;idx=0;chunks=[];setProg(0);render(); }
    function render(){
      var ll=LANGS.filter(function(x){return x[0]===lang;})[0]||LANGS[0];
      var main=(!playing&&!paused)?'<button class="wu-tts-btn" data-a="play" type="button">'+PLAY+' Play Audio</button>':(playing?'<button class="wu-tts-btn amber" data-a="pause" type="button">'+PAUSE+' Pause</button>':'<button class="wu-tts-btn" data-a="resume" type="button">'+PLAY+' Resume</button>');
      var stopBtn=(playing||paused)?'<button class="wu-tts-btn gray" data-a="stop" type="button">'+STOP+' Stop</button>':'';
      var menu=LANGS.map(function(x){return '<button type="button" data-lang="'+x[0]+'" class="'+(x[0]===lang?'sel':'')+'">'+x[1]+'</button>';}).join('');
      host.className='wu-tts';
      host.innerHTML='<div class="wu-tts-head"><div class="wu-tts-ico">'+SPK+'</div><div class="wu-tts-tt"><b>Listen to this article</b><span>'+esc(TITLE)+'</span></div><div class="wu-tts-lang"><button class="wu-tts-langbtn" data-a="langtog" type="button">&#127760; '+esc(ll[1])+' &#9662;</button><div class="wu-tts-langmenu" id="wu-tts-lm">'+menu+'</div></div><button class="wu-tts-mute" data-a="mute" title="mute" type="button">'+(muted?'&#128263;':'&#128266;')+'</button></div><div class="wu-tts-bar"><div class="wu-tts-fill" id="wu-tts-fill"></div></div><div class="wu-tts-ctrls">'+main+stopBtn+'<span class="wu-tts-pct" id="wu-tts-pct"></span></div>';
      fill=document.getElementById('wu-tts-fill'); pct=document.getElementById('wu-tts-pct');
    }
    render();
    host.addEventListener('click',function(e){
      var b=e.target.closest&&e.target.closest('[data-a],[data-lang]'); if(!b)return;
      var lng=b.getAttribute('data-lang'); if(lng){ lang=lng; if(playing||paused)stop(); render(); return; }
      var a=b.getAttribute('data-a');
      if(a==='play')start(); else if(a==='pause')pause(); else if(a==='resume')resume(); else if(a==='stop')stop();
      else if(a==='mute'){muted=!muted;render();}
      else if(a==='langtog'){var m=document.getElementById('wu-tts-lm');if(m)m.classList.toggle('open');}
    });
    document.addEventListener('click',function(e){var m=document.getElementById('wu-tts-lm');if(m&&m.classList.contains('open')&&!(e.target.closest&&e.target.closest('.wu-tts-lang')))m.classList.remove('open');});
    window.addEventListener('beforeunload',function(){try{speechSynthesis.cancel();}catch(e){}});
  })();

  /* Supabase REST helper */
  function sb(path,opts){opts=opts||{};opts.headers=Object.assign({apikey:SB_KEY,Authorization:'Bearer '+SB_KEY,'Content-Type':'application/json'},opts.headers||{});return fetch(SB_URL+'/rest/v1/'+path,opts).then(function(r){return r.ok?r.json().catch(function(){return null;}):null;}).catch(function(){return null;});}
  /* Match Blogger post -> Supabase post by exact TITLE; key everything by returned slug */
  var SLUG=null;
  var slugP=sb('posts?title=eq.'+encodeURIComponent(TITLE)+'&select=slug,views,category,featured&limit=1').then(function(d){
    var row=(d&&d[0])||null;
    if(row){
      SLUG=row.slug||null;
      if(row.views>0){var v=document.getElementById('wu-views'),vn=document.getElementById('wu-views-n');if(v&&vn){vn.textContent=row.views.toLocaleString()+' views';v.style.display='';}}
      if(row.featured){var cb=document.getElementById('wu-arth-cat');if(cb){cb.classList.add('featured');cb.innerHTML='&#9733; '+cb.innerHTML;}}
    }
    return SLUG;
  });

  /* REACTIONS (shared post_reactions: post_slug, user_token, reaction) */
  (function(){
    var row=document.getElementById('wu-react-row'); if(!row)return;
    var REACT=[['love','❤️','Love'],['laugh','😄','Laugh'],['wow','😮','Wow'],['think','🤔','Think'],['sad','😢','Sad'],['angry','😡','Angry']];
    var counts={},mine=null,u=uid();
    function draw(){ row.innerHTML=REACT.map(function(r){var c=counts[r[0]]||0;return '<button class="wu-react-btn'+(mine===r[0]?' sel':'')+'" data-r="'+r[0]+'" type="button"><span class="em">'+r[1]+'</span><span class="lb">'+r[2]+'</span><span class="ct">'+(c>0?c:'')+'</span></button>';}).join(''); }
    row.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-r]');if(!b||!SLUG)return;var type=b.getAttribute('data-r');
      if(mine===type)return;
      if(mine&&counts[mine])counts[mine]--; mine=type; counts[type]=(counts[type]||0)+1; draw();
      var bb=row.querySelector('[data-r="'+type+'"]'); if(bb){bb.classList.add('pop');setTimeout(function(){bb.classList.remove('pop');},450);}
      sb('post_reactions',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({post_slug:SLUG,user_token:u,reaction:type})});
    });
    slugP.then(function(slug){ if(!slug){row.innerHTML='<span class="wu-react-load">Reactions are unavailable for this story right now.</span>';return;}
      Promise.all([ sb('post_reactions?post_slug=eq.'+encodeURIComponent(slug)+'&select=reaction'), sb('post_reactions?post_slug=eq.'+encodeURIComponent(slug)+'&user_token=eq.'+encodeURIComponent(u)+'&select=reaction&limit=1') ]).then(function(res){
        counts={};(res[0]||[]).forEach(function(x){counts[x.reaction]=(counts[x.reaction]||0)+1;});
        mine=(res[1]&&res[1][0])?res[1][0].reaction:null; draw();
      });
    });
    draw();
  })();

  /* COMMENTS (shared comments: post_slug, author, body, flagged, parent_id) */
  (function(){
    var box=document.getElementById('wu-cm-box'),hEl=document.getElementById('wu-cm-h'); if(!box)return;
    var u=uid();
    var CMR=[['like','👍'],['love','❤️'],['laugh','😄'],['wow','😮']];
    function av(n){return ((n||'A').trim().charAt(0)||'A').toUpperCase();}
    function fmt(d){try{return new Date(d).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'});}catch(x){return '';}}
    function spammy(t){
      if(/(https?:\/\/|www\.)/i.test(t))return true;
      if(/\b(buy now|click here|free money|casino|viagra|loan offer|crypto profit|earn \$|make money fast|promo code|discount code)\b/i.test(t))return true;
      var letters=t.replace(/[^a-zA-Z]/g,'');
      if(letters.length>12){var caps=t.replace(/[^A-Z]/g,'').length;if(caps/letters.length>0.7)return true;}
      return false;
    }
    function reactBar(c,counts,mine){
      return '<div class="wu-cm-acts">'+CMR.map(function(r){var n=(counts[c.id]&&counts[c.id][r[0]])||0;var sel=(mine[c.id]===r[0])?' sel':'';return '<button class="wu-cmr-btn'+sel+'" data-cid="'+c.id+'" data-cr="'+r[0]+'" type="button">'+r[1]+(n>0?' '+n:'')+'</button>';}).join('')+(c.parent_id?'':'<button class="wu-cm-reply" data-reply="'+c.id+'" type="button">Reply</button>')+'</div>';
    }
    function itemHtml(c,counts,mine,isReply){
      return '<div class="wu-cm-item'+(isReply?' reply':'')+'" data-id="'+c.id+'"><div class="wu-cm-top"><div class="wu-cm-av">'+esc(av(c.author))+'</div><div><div class="wu-cm-nm">'+esc(c.author||'Anonymous')+'</div><div class="wu-cm-dt">'+fmt(c.created_at)+'</div></div></div><div class="wu-cm-body">'+esc(c.body)+'</div>'+reactBar(c,counts,mine)+'</div>';
    }
    function formHtml(pid){
      return '<form class="wu-cm-form" data-parent="'+(pid||'')+'"><input class="wu-cm-name" maxlength="100" placeholder="Your name (optional)"/><textarea class="wu-cm-ta" maxlength="5000" placeholder="'+(pid?'Write your reply...':'Join the discussion...')+'" rows="4"></textarea><button class="wu-cm-post" type="submit">'+(pid?'Post Reply':'Post Comment')+'</button></form>';
    }
    slugP.then(function(slug){
      if(!slug){box.innerHTML='<p class="wu-cm-empty">Comments are unavailable for this story right now.</p>';return;}
      Promise.all([
        sb('comments?post_slug=eq.'+encodeURIComponent(slug)+'&flagged=eq.false&select=id,author,body,parent_id,created_at&order=created_at.asc')
      ]).then(function(res){
        var list=res[0]||[];
        var ids=list.map(function(c){return c.id;});
        var cq=ids.length?sb('comment_reactions?comment_id=in.('+ids.map(function(x){return '"'+x+'"';}).join(',')+')&select=comment_id,reaction,user_token'):Promise.resolve([]);
        cq.then(function(crs){
          crs=crs||[];
          var counts={},mine={};
          crs.forEach(function(r){counts[r.comment_id]=counts[r.comment_id]||{};counts[r.comment_id][r.reaction]=(counts[r.comment_id][r.reaction]||0)+1;if(r.user_token===u)mine[r.comment_id]=r.reaction;});
          var tops=list.filter(function(c){return !c.parent_id;});
          var kids={};list.forEach(function(c){if(c.parent_id){kids[c.parent_id]=kids[c.parent_id]||[];kids[c.parent_id].push(c);}});
          if(hEl)hEl.textContent='Comments ('+list.length+')';
          var items=tops.map(function(c){
            var h=itemHtml(c,counts,mine,false);
            (kids[c.id]||[]).forEach(function(k){h+=itemHtml(k,counts,mine,true);});
            return h;
          }).join('');
          box.innerHTML=formHtml(null)+'<div class="wu-cm-list" id="wu-cm-list">'+(items||'<p class="wu-cm-empty">Be the first to share your thoughts.</p>')+'</div>';
          /* submit (top-level + replies via delegation) */
          box.addEventListener('submit',function(e){
            var f=e.target.closest&&e.target.closest('.wu-cm-form'); if(!f)return; e.preventDefault();
            var ta=f.querySelector('.wu-cm-ta'),nm=f.querySelector('.wu-cm-name'),btn=f.querySelector('.wu-cm-post');
            var txt=(ta.value||'').trim(); if(txt.length<2){ta.focus();return;}
            var flagged=spammy(txt);
            var payload={post_slug:slug,author:((nm.value||'').trim().slice(0,100))||'Anonymous',body:txt,flagged:flagged};
            var pid=f.getAttribute('data-parent'); if(pid)payload.parent_id=pid;
            btn.disabled=true;btn.textContent='Posting...';
            sb('comments',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)}).then(function(d){
              if(!d){btn.disabled=false;btn.textContent='Post Comment';return;}
              if(flagged){f.outerHTML='<div class="wu-cm-held">Thanks! Your comment was held for review and will appear once approved.</div>';return;}
              var row=(d&&d[0])||payload; row.id=row.id||('tmp'+Date.now()); row.created_at=row.created_at||new Date().toISOString();
              var html=itemHtml(row,{},{},!!pid);
              if(pid){var host2=box.querySelector('.wu-cm-item[data-id="'+pid+'"]');if(host2)host2.insertAdjacentHTML('afterend',html);f.remove();}
              else{var lst=document.getElementById('wu-cm-list');if(lst){var emp=lst.querySelector('.wu-cm-empty');if(emp)emp.remove();lst.insertAdjacentHTML('afterbegin',html);}ta.value='';btn.disabled=false;btn.textContent='Post Comment';}
            });
          });
          /* reply + comment reactions via delegation */
          box.addEventListener('click',function(e){
            var rp=e.target.closest&&e.target.closest('[data-reply]');
            if(rp){var cid=rp.getAttribute('data-reply');var it=box.querySelector('.wu-cm-item[data-id="'+cid+'"]');if(it&&!it.querySelector('.wu-cm-form')){it.insertAdjacentHTML('beforeend',formHtml(cid));}return;}
            var rb=e.target.closest&&e.target.closest('[data-cr]');
            if(rb){var cid2=rb.getAttribute('data-cid'),type=rb.getAttribute('data-cr');
              if(mine[cid2]===type)return;
              counts[cid2]=counts[cid2]||{};
              if(mine[cid2]&&counts[cid2][mine[cid2]])counts[cid2][mine[cid2]]--;
              mine[cid2]=type;counts[cid2][type]=(counts[cid2][type]||0)+1;
              var it2=box.querySelector('.wu-cm-item[data-id="'+cid2+'"]');
              if(it2){var bar=it2.querySelector('.wu-cm-acts');var c0=list.filter(function(x){return String(x.id)===String(cid2);})[0]||{id:cid2,parent_id:null};if(bar)bar.outerHTML=reactBar(c0,counts,mine);}
              sb('comment_reactions',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({comment_id:cid2,user_token:u,reaction:type})});
            }
          });
        });
      });
    });
  })();

  /* RELATED: label section + "More in {Category}" (glass cards) */
  (function(){
    var host=document.getElementById('wu-related'); if(!host)return;
    var label=null,cat=null,catLink=document.getElementById('wu-arth-cat');
    if(catLink){ var h=catLink.getAttribute('href')||''; if(h.indexOf('/search/label/')>-1)label=decodeURIComponent(h.split('/search/label/')[1]).replace(/\/$/,''); }
    WU_TAX.forEach(function(t){if(t.n===label||t.l.indexOf(label)>-1)cat=t.n;});
    var seen={}; seen[PURL]=1;
    function dedup(arr){return arr.filter(function(e){var u2=wuAlt(e);if(seen[u2])return false;seen[u2]=1;return true;});}
    function section(title,sub,posts){ if(!posts.length)return ''; return '<section class="wu-rel"><div class="wu-container"><h2 class="wu-rel-h">'+wuEsc(title)+'</h2><p class="wu-rel-sub">'+wuEsc(sub)+'</p><div class="wu-grid">'+posts.slice(0,6).map(function(e){return wuGCard(e);}).join('')+'</div></div></section>'; }
    var r1=(label&&label!==cat)?wuByLabel(label,14):Promise.resolve([]);
    var r2=cat?wuByLabel(cat,14):Promise.resolve([]);
    var r3=wuFeed('/feeds/posts/default?alt=json&max-results=14');
    Promise.all([r1,r2,r3]).then(function(r){
      var rel=dedup(r[0]), catp=dedup(r[1]), rec=dedup(r[2]);
      var html='';
      if(label&&label!==cat)html+=section('More on '+label,'Related stories from the same topic',rel);
      if(cat)html+=section('More in '+cat,'Related stories from the same category',catp);
      if(!html)html+=section('Recommended For You','More stories you might enjoy',rec);
      host.innerHTML=html;
    });
  })();
})();

/* SHARE HELPERS */
function wuShare(){if(navigator.share){navigator.share({title:document.title,url:location.href}).catch(function(){});}else{wuCopy();}}
function wuShareX(){window.open('https://twitter.com/intent/tweet?text='+encodeURIComponent(document.title)+'&url='+encodeURIComponent(location.href),'_blank','width=600,height=400');}
function wuShareFB(){window.open('https://www.facebook.com/sharer/sharer.php?u='+encodeURIComponent(location.href),'_blank','width=600,height=400');}
function wuShareWA(){window.open('https://wa.me/?text='+encodeURIComponent(document.title+' '+location.href),'_blank');}
function wuCopy(){var b=document.getElementById('wu-copy');var done=function(){if(b){b.textContent='Copied!';setTimeout(function(){b.textContent='Copy Link';},2000);}};if(navigator.clipboard){navigator.clipboard.writeText(location.href).then(done).catch(function(){wuFb(done);});}else{wuFb(done);}}
function wuFb(cb){var ta=document.createElement('textarea');ta.value=location.href;ta.style.cssText='position:fixed;left:-9999px;';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');cb();}catch(e){}document.body.removeChild(ta);}
/* 404 countdown -> auto redirect home in 10s */
(function(){var el=document.getElementById('wu-404-count');if(!el)return;var s=10;var t=setInterval(function(){s--;if(el)el.textContent=s<0?0:s;if(s<=0){clearInterval(t);location.href='/';}},1000);})();
